import 'package:collection/collection.dart';

Future<List<Event>> topK(Stream<Event> events, int k) async {
  final heap = HeapPriorityQueue<Event>((a, b) => a.score.compareTo(b.score));
  // min-heap: heap.first is the weakest survivor

  // `listen` would return at once with an empty heap; drain the stream first.
  await for (final e in events) {
    if (heap.length < k) {
      heap.add(e);
    } else if (e.score > heap.first.score) {
      heap.removeFirst();          // evict the weakest
      heap.add(e);
    }
  }

  final out = <Event>[];
  while (heap.isNotEmpty) out.add(heap.removeFirst());
  return out.reversed.toList();    // descending
}

// ── The heap itself, when they ask you to implement it ──
class MinHeap {
  final List<int> _a = [];

  int get length => _a.length;
  int get peek => _a.first;

  void add(int v) {
    _a.add(v);
    var i = _a.length - 1;
    while (i > 0) {
      final parent = (i - 1) ~/ 2;
      if (_a[parent] <= _a[i]) break;
      _swap(parent, i);
      i = parent;
    }
  }

  int removeMin() {
    final min = _a.first;
    _a[0] = _a.last;
    _a.removeLast();
    var i = 0;
    while (true) {
      final l = 2 * i + 1, r = 2 * i + 2;
      var smallest = i;
      if (l < _a.length && _a[l] < _a[smallest]) smallest = l;
      if (r < _a.length && _a[r] < _a[smallest]) smallest = r;
      if (smallest == i) break;
      _swap(i, smallest);
      i = smallest;
    }
    return min;
  }

  void _swap(int i, int j) {
    final t = _a[i];
    _a[i] = _a[j];
    _a[j] = t;
  }
}

