// ── Safe truncation for a bio field ──
String truncate(String s, int max) =>
    s.characters.length <= max ? s : '${s.characters.take(max)}...';

// ── Palindrome over characters, not code units ──
bool isPalindrome(String s) {
  final chars = s.toLowerCase().characters.where((c) => c.trim().isNotEmpty).toList();
  for (var i = 0, j = chars.length - 1; i < j; i++, j--) {
    if (chars[i] != chars[j]) return false;
  }
  return true;
}

