// The loop itself, for when they ask you to write it
void fisherYates<T>(List<T> a, Random rng) {
  for (var i = a.length - 1; i > 0; i--) {
    final j = rng.nextInt(i + 1);   // ❗ i + 1, not a.length — that version is biased
    final tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;
  }
}

// Pick k of n without duplicates — partial shuffle, O(k) rather than O(n)
List<T> sample<T>(List<T> source, int k, Random rng) {
  final a = List.of(source);
  final n = min(k, a.length);
  for (var i = 0; i < n; i++) {
    final j = i + rng.nextInt(a.length - i);
    final tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;
  }
  return a.sublist(0, n);
}

// Stream of unknown length — reservoir sampling, memory is O(k)
Future<List<T>> reservoir<T>(Stream<T> items, int k, Random rng) async {
  final keep = <T>[];
  var seen = 0;
  await for (final item in items) {
    if (keep.length < k) {
      keep.add(item);
    } else {
      final j = rng.nextInt(seen + 1);   // survives with probability k / (seen + 1)
      if (j < k) keep[j] = item;
    }
    seen++;
  }
  return keep;
}

