int byDay(Event a, Event b) => a.day.compareTo(b.day);

// ✅ Boundary search: the first index whose value is >= target
int lowerBoundOf(List<int> a, int target) {
  var lo = 0, hi = a.length;             // hi is EXCLUSIVE
  while (lo < hi) {
    final mid = lo + (hi - lo) ~/ 2;     // mid < hi always -> the range shrinks
    if (a[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid;                          // keep mid: it may itself be the answer
    }
  }
  return lo;                             // a.length when every value is smaller
}

