// Build once: O(n), with one extra slot so an empty range needs no special case
List<int> buildPrefix(List<int> values) {
  final prefix = List<int>.filled(values.length + 1, 0);
  for (var i = 0; i < values.length; i++) {
    prefix[i + 1] = prefix[i] + values[i];
  }
  return prefix;
}

// Query: O(1) over the half-open range [l, r)
int rangeSum(List<int> prefix, int l, int r) => prefix[r] - prefix[l];

// A 30-day rolling total for every point: O(n) instead of O(n * 30)
List<int> rolling(List<int> daily, int window) {
  final prefix = buildPrefix(daily);
  return [
    for (var i = 0; i < daily.length; i++)
      rangeSum(prefix, max(0, i - window + 1), i + 1),
  ];
}

// ❌ What the screen was doing: the inner loop re-reads the same 30 values
int rollingSlow(List<int> daily, int i, int window) {
  var sum = 0;
  for (var j = max(0, i - window + 1); j <= i; j++) {
    sum += daily[j];
  }
  return sum;
}

// Range UPDATES: difference array — m updates in O(m + n), not O(m * k)
List<int> applyRanges(int n, List<({int from, int to, int amount})> updates) {
  final diff = List<int>.filled(n + 1, 0);
  for (final u in updates) {
    diff[u.from] += u.amount;
    diff[u.to + 1] -= u.amount;   // one write per endpoint, not one per element
  }
  final out = List<int>.filled(n, 0);
  var running = 0;
  for (var i = 0; i < n; i++) {
    running += diff[i];
    out[i] = running;
  }
  return out;
}

