// ── A dense bitset of 100k ids: 1 bit each, 32-bit safe everywhere ──
class BitSet {
  BitSet(int size) : _words = Uint32List((size + 31) >> 5);
  final Uint32List _words;

  bool operator [](int i) => _words[i >> 5] & (1 << (i & 31)) != 0;
  void set(int i) => _words[i >> 5] |= 1 << (i & 31);
  void clear(int i) => _words[i >> 5] &= ~(1 << (i & 31));

  int get cardinality {
    var n = 0;
    for (final w in _words) {
      var v = w;
      while (v != 0) {
        v &= v - 1;   // clears the lowest set bit — one iteration per set bit
        n++;
      }
    }
    return n;
  }
}

class LruCache<K, V> {
  LruCache(this.capacity);
  final int capacity;
  // LinkedHashMap: iteration order == insertion order, so keys.first is the LRU
  final _entries = <K, V>{};

  V? get(K key) {
    if (!_entries.containsKey(key)) return null;
    final value = _entries.remove(key) as V;
    _entries[key] = value;      // re-insert -> moves to the most-recent end
    return value;
  }

  void put(K key, V value) {
    _entries.remove(key);       // ❗ without this, an update keeps the OLD position
    _entries[key] = value;
    while (_entries.length > capacity) {
      _entries.remove(_entries.keys.first);   // first key == least recently used
    }
  }
}

// ❌ FIFO in an LRU costume: reads never refresh recency, updates never move
class NotAnLru<K, V> {
  final _entries = <K, V>{};
  V? get(K key) => _entries[key];
  void put(K key, V value) {
    _entries[key] = value;
    if (_entries.length > 100) _entries.remove(_entries.keys.first);
  }
}

// Bound by bytes — what an image cache actually cares about
class ByteLru {
  ByteLru(this.maxBytes);
  final int maxBytes;
  int _bytes = 0;
  final _entries = <String, List<int>>{};

  void put(String key, List<int> data) {
    final old = _entries.remove(key);
    if (old != null) _bytes -= old.length;
    _entries[key] = data;
    _bytes += data.length;
    while (_bytes > maxBytes && _entries.isNotEmpty) {
      final k = _entries.keys.first;
      _bytes -= _entries.remove(k)!.length;
    }
  }
}

