class DisjointSet<T> {
  final Map<T, T> _parent = {};
  final Map<T, int> _size = {};

  void add(T x) {
    _parent.putIfAbsent(x, () => x);
    _size.putIfAbsent(x, () => 1);
  }

  // Iterative: recursion here overflows the stack on a long chain
  T find(T x) {
    add(x);
    var root = x;
    while (_parent[root] != root) {
      root = _parent[root] as T;
    }
    var cur = x;
    while (cur != root) {          // path compression: flatten what we walked
      final next = _parent[cur] as T;
      _parent[cur] = root;
      cur = next;
    }
    return root;
  }

  /// Returns false when the two were already merged — i.e. this edge closes a cycle.
  bool union(T a, T b) {
    var ra = find(a), rb = find(b);
    if (ra == rb) return false;
    if (_size[ra]! < _size[rb]!) {  // union by size: small tree under large root
      final t = ra;
      ra = rb;
      rb = t;
    }
    _parent[rb] = ra;
    _size[ra] = _size[ra]! + _size[rb]!;
    return true;
  }

  bool sameSet(T a, T b) => find(a) == find(b);
}

