// Cycle detection falls out of the return value
bool hasCycle(List<(int, int)> edges) {
  final ds = DisjointSet<int>();
  for (final (a, b) in edges) {
    if (!ds.union(a, b)) return true;
  }
  return false;
}

// The buckets, when you finally need them
Map<String, List<String>> groups(DisjointSet<String> ds, Iterable<String> ids) {
  final out = <String, List<String>>{};
  for (final id in ids) {
    out.putIfAbsent(ds.find(id), () => []).add(id);
  }
  return out;
}

