class TrieNode {
  final Map<String, TrieNode> children = {};
  final List<int> topIds = [];   // small ranked payload, filled at index time
  bool isWord = false;
}

class Trie {
  final _root = TrieNode();

  /// Insert in ranked order, so topIds is already the ranking.
  void insert(String word, int id) {
    var node = _root;
    for (final ch in word.characters) {
      node = node.children.putIfAbsent(ch.toString(), TrieNode.new);
      if (node.topIds.length < 5) node.topIds.add(id);
    }
    node.isWord = true;
  }

  List<int> suggest(String prefix) {
    var node = _root;
    for (final ch in prefix.characters) {
      final next = node.children[ch.toString()];
      if (next == null) return const [];   // O(m), independent of dataset size
      node = next;
    }
    return node.topIds;                    // no DFS needed: precomputed
  }
}

// ── The alternative that usually ships: sorted list + binary search ──
class PrefixIndex {
  PrefixIndex(List<String> names) : _sorted = List.of(names)..sort();
  final List<String> _sorted;

  List<String> suggest(String prefix, {int limit = 20}) {
    final out = <String>[];
    for (var i = lowerBound(_sorted, prefix); i < _sorted.length; i++) {
      if (!_sorted[i].startsWith(prefix)) break;   // the matching run ends here
      out.add(_sorted[i]);
      if (out.length == limit) break;
    }
    return out;
  }
}

