List<List<int>> combinationSum(List<int> candidates, int target) {
  final nums = List.of(candidates)..sort();   // sorting is what makes pruning possible
  final results = <List<int>>[];
  final path = <int>[];

  void backtrack(int start, int remaining) {
    if (remaining == 0) {
      results.add(List.of(path));   // ✅ snapshot
      // ❌ results.add(path) -> n references to one list, empty when this returns
      return;
    }
    for (var i = start; i < nums.length; i++) {
      if (nums[i] > remaining) break;                     // sorted: later ones fail too
      if (i > start && nums[i] == nums[i - 1]) continue;  // no duplicate combinations
      path.add(nums[i]);                                  // choose
      backtrack(i + 1, remaining - nums[i]);              // explore (i to allow reuse)
      path.removeLast();                                  // un-choose
    }
  }

  backtrack(0, target);
  return results;
}

// Permutations use `used` instead of `start`, because order matters here
void permute(List<int> a, List<bool> used, List<int> path, List<List<int>> out) {
  if (path.length == a.length) {
    out.add(List.of(path));
    return;
  }
  for (var i = 0; i < a.length; i++) {
    if (used[i]) continue;
    used[i] = true;
    path.add(a[i]);
    permute(a, used, path, out);
    path.removeLast();
    used[i] = false;
  }
}

// Lazy: the caller can stop after 20 results instead of enumerating all 2^n
Iterable<List<int>> subsets(List<int> a, [int i = 0, List<int>? path]) sync* {
  final current = path ?? <int>[];
  if (i == a.length) {
    yield List.of(current);   // still a copy: the generator keeps mutating `current`
    return;
  }
  yield* subsets(a, i + 1, current);
  current.add(a[i]);
  yield* subsets(a, i + 1, current);
  current.removeLast();
}
